UPDATE BID_PREP_FORM
   SET CUR_VER = #{next}, UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE BID_CASE_ID = #{bidCaseId} AND FORM_CD = #{formCd} AND CUR_VER = #{base} AND CONFIRMED_VER IS NULL

UPDATE BID_PREP_FORM
   SET CONFIRMED_VER = NULL, CONFIRMED_SHA256 = NULL, CONFIRMED_BY = NULL, CONFIRMED_VERIFIED = 0,
       CONFIRMED_AT = NULL, UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE BID_CASE_ID = #{bidCaseId} AND FORM_CD = #{formCd} AND CONFIRMED_VER = #{ver}

