SELECT IMPORT_ID, FILE_DATE FROM INST_PLAN_IMPORT
 WHERE INSTITUTION_ID = #{institutionId}
   AND IMPORT_ID = (SELECT MAX(IMPORT_ID) FROM INST_PLAN_IMPORT WHERE INSTITUTION_ID = #{institutionId})
